def test_no_page_texts_degrades_safely():
    """L13 退化路径: 无 page_texts(旧调用方/OCR 缓存缺失页文本)时, L12 行为不变——
    p2r6 不携伪单价 ok 入库(撕裂反算 3498.77 只能 needs_review), p2r8 q 置空不残留
    左半区窜入伪量, 其余 9 行仍精确。"""
    items, _ = _extract_from_tables([_table(2), _table(3)], "test://noPT", _SEEDS)
    for it in items:
        k = (it.get("source_page"), it.get("source_row_idx"))
        up = it.get("unit_price")
        if k == (2, 6):
            assert it.get("validation_status") == "needs_review" or up is None, (k, it)
            assert up is None or abs(up - 3496.0) > 0.011, (k, up)
        if up is None:
            continue
        for fk in (3559.22, 4313.46, 3663.86, 512.91, 242.10, 53.0):
            if abs(up - fk) < 1e-9:
                assert it.get("validation_status") == "needs_review", (k, it)
        if it.get("validation_status") == "ok" and k in TRUTH_POSITIVE:
            assert abs(up - TRUTH_POSITIVE[k][5]) < 0.011, (k, up, TRUTH_POSITIVE[k][5])


def _table_no_bboxes(pg):
    d = _DOC[str(pg)]
    return SimpleNamespace(
        page_no=pg,
        table_idx=0,
        rows=[list(r) for r in d["rows"]],
        cell_bboxes=None,
        mean_confidence=d["mean_confidence"],
    )


_FAKE_SIGNATURES = (3559.22, 4313.46, 3663.86, 512.91, 242.10, 58.56, 267.0, 53.0)


def test_no_bboxes_degraded_arbitration_needs_review():
    """评审 major 修复: 调价表 cell_bboxes 缺失(roles_x/右半区锚带不可用 →
    adj_floor=None)时仲裁无几何背书——×1.14 窗口可捕获左半区原合价(3559.22 伪
    签名)、费用碎片级联(58.56/267.0)与第九层佐证失义——含税仲裁/含税升级的
    改写行一律 needs_review(『待核验: 调价表无坐标带,仲裁降级』), 伪值不得以
    ok 入库; 价格值保留供人工核验。带 bboxes 主路径不受影响(上方真值表守门)。"""
    items, meta = _extract_from_tables([_table_no_bboxes(2), _table_no_bboxes(3)], "test://nobbox", _SEEDS)
    assert meta["matched_seeds"], meta
    degraded = 0
    for it in items:
        up = it.get("unit_price")
        if up is None:
            continue
        if it.get("price_reason") == "待核验: 调价表无坐标带,仲裁降级":
            degraded += 1
            assert it.get("validation_status") == "needs_review", (it.get("source_row_idx"), it)
        for fk in _FAKE_SIGNATURES:
            if abs(up - fk) < 0.011:
                assert it.get("validation_status") == "needs_review", (
                    it.get("source_page"),
                    it.get("source_row_idx"),
                    up,
                    it.get("validation_status"),
                    it.get("price_reason"),
                )
    assert degraded >= 1, "降级标注通道未生效(fixture 在无 bboxes 下必有仲裁改写行)"


def test_no_bboxes_with_page_texts_same_guard():
    """降级守卫 × L13 页文本通道组合(评审指出该组合零 fixture): 有页文本无
    bboxes 时, 伪签名值同样只能 needs_review 入库; L13 缺量恢复门关闭
    (adj_floor 缺失时不从未裁候选注量)。"""
    items, meta = _extract_from_tables(
        [_table_no_bboxes(2), _table_no_bboxes(3)],
        "test://nobbox-pt",
        _SEEDS,
        page_texts={int(k): v for k, v in _PAGE_TEXTS.items()},
    )
    assert meta["matched_seeds"], meta
    for it in items:
        up = it.get("unit_price")
        if up is None:
            continue
        for fk in _FAKE_SIGNATURES:
            if abs(up - fk) < 0.011:
                assert it.get("validation_status") == "needs_review", (
                    it.get("source_page"),
                    it.get("source_row_idx"),
                    up,
                    it.get("validation_status"),
                    it.get("price_reason"),
                )
        q = it.get("quantity")
        # L13 缺量恢复门关闭: 无锚带时不允许从页文本+未裁候选注入新量
        # (守卫前该通道存在;真量恢复仅在有坐标带的主路径声明)。
        if it.get("price_reason") == "待核验: 调价表无坐标带,仲裁降级" and q is not None:
            assert (it.get("source_page"), it.get("source_row_idx")) not in ((2, 4), (2, 6)), (
                "降级行不得经 L13 注量",
                it,
            )
